export function actorSourceRect(kind,row,col){
 const sheet=ACTOR_SHEETS[kind],rect=sheet?.rows[row]?.[col];
 const pivot=ACTOR_SOURCE_ANCHORS[kind]?.[row]?.[col];
 return rect?{x:rect[0],y:rect[1],w:rect[2]-rect[0],h:rect[3]-rect[1],...(pivot?{anchorX:pivot[0],anchorY:pivot[1],bodyHeight:pivot[2]}:{})}:null;
}
export function prepareActorAtlas(image,kind){
 const sheet=ACTOR_SHEETS[kind];if(!sheet)throw Error('Unknown actor atlas '+kind);
 const cell=224,out=document.createElement('canvas');out.width=cell*8;out.height=cell*sheet.rows.length;
 const c=out.getContext('2d'),sx=image.width/sheet.width,sy=image.height/sheet.height;
 sheet.rows.forEach((row,r)=>row.forEach((rect,col)=>{
  // One source scale per sheet; never independently resize an individual pose.
  const [l,t,right,bottom]=rect,x=Math.max(0,l-1),y=Math.max(0,t-1),w=Math.min(sheet.width,right+1)-x,h=Math.min(sheet.height,bottom+1)-y;
  const dw=w*sheet.scale,dh=h*sheet.scale;
  c.drawImage(image,x*sx,y*sy,w*sx,h*sy,col*cell+(cell-dw)/2,(r+1)*cell-8-dh,dw,dh);
 }));
 return cutoutAtlas(out,8,sheet.rows.length);
}
